import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { setDataAnchor, recheckLine } from '../../src/lib/parse.js'
import data from '../../src/data.json'

const here = dirname(fileURLToPath(import.meta.url))
const ROOT = join(here, '..', '..', '..')

/**
 * The README intro paragraph (<!-- INTRO:START -->…<!-- INTRO:END -->) is
 * generated by scripts/readme-stats.mjs. It used to be hand-written prose and
 * silently drifted (it kept claiming "302 models ... fact-checked Oct 8" long
 * after the catalog passed 300 rows) — nothing caught it, because no gate
 * compared the README prose to the data.
 *
 * This test is that gate: the intro must state the CURRENT model count and
 * carry the exact recheck line the site renders (parse.recheckLine()), so the
 * README and the live site can never tell different stories about the catalog.
 */
describe('README intro block (generated, never stale)', () => {
  const readme = readFileSync(join(ROOT, 'README.md'), 'utf8')

  it('has the INTRO markers with a non-empty paragraph between them', () => {
    expect(readme, 'README INTRO:START marker').toContain('<!-- INTRO:START -->')
    expect(readme, 'README INTRO:END marker').toContain('<!-- INTRO:END -->')
    const m = readme.match(/<!-- INTRO:START -->\n([\s\S]*?)\n<!-- INTRO:END -->/)
    expect(m, 'README INTRO block parses').not.toBeNull()
    expect(m![1].trim().length).toBeGreaterThan(0)
  })

  it('states the current model count, not a stale one', () => {
    const dj = data as { model_count: number }
    const m = readme.match(/<!-- INTRO:START -->\n([\s\S]*?)\n<!-- INTRO:END -->/)
    const intro = m![1]
    expect(intro, 'README intro model count').toContain(`**${dj.model_count} models**`)
    expect(intro, 'README intro rank range').toContain(`CSV ranks 1-${dj.model_count}`)
  })

  it('carries exactly the recheck line the site renders', () => {
    const dj = data as { data_as_of: string; model_count: number; rechecked_count: number }
    setDataAnchor(dj.data_as_of, dj.rechecked_count, dj.model_count)
    const expected = recheckLine()
    const m = readme.match(/<!-- INTRO:START -->\n([\s\S]*?)\n<!-- INTRO:END -->/)
    expect(m![1], 'README intro carries the site recheck line').toContain(expected)
  })
})
